CREATE FUNCTION f3() RETURNS int
BEGIN
DECLARE a, b int;
DROP TEMPORARY TABLE IF EXISTS t3;
CREATE TEMPORARY TABLE t3 (id INT);
INSERT INTO t3 VALUES (1), (2), (3);
SET a:= (SELECT COUNT(*) FROM t3);
SET b:= (SELECT COUNT(*) FROM t3 t3_alias);
RETURN a + b;
END

CREATE FUNCTION f4() RETURNS int
BEGIN
DECLARE x int;
DECLARE c CURSOR FOR SELECT * FROM t1 limit 1;
SET NAMES 'utf8mb3';
SET @var1=20;
OPEN c;
FETCH c INTO x;
CLOSE c;
RETURN x;
END

CREATE PROCEDURE cursor1()
BEGIN
DECLARE v1 int;
DECLARE done INT DEFAULT FALSE;
DECLARE cur1 CURSOR FOR SELECT * FROM t1;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
SET @@session.transaction_isolation='READ-COMMITTED';
OPEN cur1;
read_loop: LOOP
FETCH cur1 INTO v1;
IF done THEN
LEAVE read_loop;
END IF;
END LOOP;
SELECT v1;
CLOSE cur1;
END

CREATE PROCEDURE cursor2()
BEGIN
DECLARE x int;
DECLARE y int;
DECLARE c1 CURSOR FOR SELECT * FROM t1 limit 1;
DECLARE c2 CURSOR FOR SELECT * FROM t2 limit 1;
SET @@session.transaction_isolation='READ-COMMITTED';
OPEN c1;
OPEN c2;

FETCH c1 INTO x;
FETCH c2 INTO y;
SELECT (x+y);
SELECT "session state sent as part of above SELECT" AS col_heading;
CLOSE c1;
CLOSE c2;
END

CREATE PROCEDURE t_cache()
BEGIN
SET @A= 20;
SELECT * FROM t1;
SELECT * FROM t1;
PREPARE x FROM 'SELECT 1';
SELECT * FROM t1;
SELECT * FROM t1;
END

