CREATE FUNCTION seq_1_to_2() RETURNS INT
BEGIN
DECLARE limit_value, return_value INT;
SET limit_value = 2;
SELECT c1 INTO return_value FROM tr;
IF (return_value < limit_value) THEN
UPDATE tr SET c1 = c1 + 1;
ELSE
UPDATE tr SET c1 = 1;
END IF;
RETURN (return_value);
END

