create procedure proc_26977_broken(v int)
begin
declare i int default 5;

declare continue handler for sqlexception
begin
select 'caught something';
retry:
while i > 0 do
begin
set i = i - 1;
select 'looping', i;
end;
end while retry;
end;

select 'do something';
insert into t1 values (v);
select 'do something again';
insert into t1 values (v);
end

