CREATE PROCEDURE cursor_over_union(OUT sum_a INTEGER, OUT sum_b INTEGER)
BEGIN
DECLARE a INTEGER;
DECLARE b INTEGER;
DECLARE done INTEGER DEFAULT 0;
DECLARE c1 CURSOR FOR
SELECT t1.a, t1.b FROM t1
UNION DISTINCT
SELECT t2.c, t2.d FROM t2;
DECLARE c2 CURSOR FOR
SELECT t1.a, t1.b FROM t1
UNION ALL
SELECT t2.c, t2.d FROM t2;
DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET done = 1;

SET sum_a = 0;
SET sum_b = 0;

OPEN c1;
REPEAT
FETCH c1 INTO a, b;
if NOT done THEN
SET sum_a = sum_a + a;
SET sum_b = sum_b + b;
END IF;
UNTIL done END REPEAT;
CLOSE c1;

SET done = 0;

OPEN c2;
REPEAT
FETCH c2 INTO a, b;
if NOT done THEN
SET sum_a = sum_a + a;
SET sum_b = sum_b + b;
END IF;
UNTIL done END REPEAT;
CLOSE c2;

end

