CASE EXISTS(SELECT 1
FROM tmp d
LEFT JOIN information_schema.columns c
ON c.table_schema = 'test' AND
upper(c.column_name) = upper(d.name)
WHERE c.table_schema IS NULL
)
WHEN TRUE THEN SELECT 'true';
