CASE
WHEN EXISTS(SELECT 1
FROM tmp d
LEFT JOIN information_schema.columns c
ON c.table_schema = 'test' AND
upper(c.column_name) = upper(d.name)
WHERE c.table_schema IS NULL
)
THEN SELECT 'true';
ELSE SELECT 'false';
END CASE;

WHILE EXISTS(SELECT 1
FROM tmp d
LEFT JOIN information_schema.columns c
ON c.table_schema = 'test' AND
upper(c.column_name) = upper(d.name)
WHERE c.table_schema IS NULL
)
DO
SELECT 'while';
END WHILE;

REPEAT
SELECT 'repeat';
UNTIL NOT
EXISTS(SELECT 1
FROM tmp d
LEFT JOIN information_schema.columns c
ON c.table_schema = 'test' AND
upper(c.column_name) = upper(d.name)
WHERE c.table_schema IS NULL
)
END REPEAT;
DROP TEMPORARY TABLE tmp;
END;

